// === Tab: sketch ===
// By Roni Kaufman
// https://ronikaufman.github.io

// inspiration: https://iquilezles.org/articles/warp/

let m = 12, n = 8; // number of films in width and height
let s = 80, h = s*Math.sqrt(3)/2; // length of the side of each triangle

let palette = ["#fafafa", "#fafafa", "#71859d", "#f6d448"];

// background
let theShader;

// foreground
let grph;

function preload() {
  theShader = createShader(vert, frag);
}

function setup() {
  createCanvas(m*s/2, n*h, WEBGL);

  let colors = [];
  let erased = [];
  for (let j = 0; j < n; j++) {
    let newLineColors = [];
    let newLineErased = [];
    for (let i = 0; i < m+1; i++) {
      let adjacentColors = [];
      if (i > 0) adjacentColors.push(newLineColors[i-1]);
      if (j > 0 && (i+j) % 2 == 1) adjacentColors.push(colors[j-1][i]);
      let col;
      do {
        col = random(palette);
      } while (adjacentColors.indexOf(col) != -1)
      newLineColors.push(col);

      let canBeErased = true;
      if (i > 0 && newLineErased[i-1]) canBeErased = false;
      if (j > 0 && (i+j) % 2 == 1 && erased[j-1][i]) canBeErased = false;
      newLineErased.push(canBeErased && random() < 1/2);
    }
    colors.push(newLineColors);
    erased.push(newLineErased);
  }

  grph = createGraphics(width, height);
  grph.strokeWeight(s/5);
  grph.strokeCap(SQUARE);
  for (let i = 0; i < m+1; i++) {
    let x = i*s/2;
    for (let j = 0; j < n; j++) {
      let y = j*h;
      var col = colors[j][i];
      let era = erased[j][i];
      if ((i+j) % 2 == 0) {
        makeTriangle(x, y, x+s/2, y+h, x-s/2, y+h, col, era);
      } else {
        makeTriangle(x-s/2, y, x+s/2, y, x, y+h, col, era);
      }
    }
  }
}

function draw() {
  // background
  theShader.setUniform("u_resolution", [width / 1, height / 1]);

  shader(theShader);

  push();
  translate(0, 0, -height / 2-1);
  box(width, height);
  pop();

  resetShader();

  // foreground
  image(grph, -width/2, -height/2);
}

function makeTriangle(xA, yA, xB, yB, xC, yC, col, era) {
  let x0 = (xA+xB+xC)/3, y0 = (yA+yB+yC)/3;

  grph.push();
  grph.translate(x0, y0);
  grph.rotate(random([0, TAU/3, 2*TAU/3]));
  grph.translate(-x0, -y0);

  grph.noStroke();
  if (era) grph.erase();
  else grph.fill(col);
  grph.triangle(xA, yA, xB, yB, xC, yC);
  grph.noErase();

  grph.noFill();
  grph.stroke(col);
  if (!era) grph.erase();
  grph.arc(xA, yA, s, s, atan2(yB-yA, xB-xA), atan2(yC-yA, xC-xA));
  grph.noErase();

  grph.pop();
}

// === Tab: frag ===
const frag = `
  #ifdef GL_ES
  precision mediump float;
  #endif

  varying vec2 vTexCoord;

  uniform vec2 u_resolution;
  //uniform vec2 u_mouse;
  //uniform float u_time;

  float random(in vec2 st) {
      return fract(sin(dot(st.xy,
                           vec2(12.9898,78.233)))
                   * 43758.5453123);
  }

  // 2D Noise based on Morgan McGuire @morgan3d
  // https://www.shadertoy.com/view/4dS3Wd
  float noise (in vec2 st) {
      vec2 i = floor(st);
      vec2 f = fract(st);

      // Four corners in 2D of a tile
      float a = random(i);
      float b = random(i + vec2(1.0, 0.0));
      float c = random(i + vec2(0.0, 1.0));
      float d = random(i + vec2(1.0, 1.0));

      // Smooth Interpolation

      // Cubic Hermine Curve.  Same as SmoothStep()
      vec2 u = f*f*(3.0-2.0*f);
      // u = smoothstep(0.,1.,f);

      // Mix 4 coorners percentages
      return mix(a, b, u.x) +
              (c - a)* u.y * (1.0 - u.x) +
              (d - b) * u.x * u.y;
  }

  float fbm(in vec2 x) {    
      float H = 1.;
      float G = exp2(-H);
      float f = 1.0;
      float a = 1.0;
      float t = 0.0;
      const int numOctaves = 5;
			/*
      for (int i = 0; i < numOctaves; i++) {
          t += a*noise(f*x);
          f *= 2.0;
          a *= G;
      }
			*/
			// i = 0
			t += a*noise(f*x);
      f *= 2.0;
      a *= G;
			// i = 1
			t += a*noise(f*x);
      f *= 2.0;
      a *= G;
			// i = 2
			t += a*noise(f*x);
      f *= 2.0;
      a *= G;
			// i = 3
			t += a*noise(f*x);
      f *= 2.0;
      a *= G;
			// i = 4
			t += a*noise(f*x);
      f *= 2.0;
      a *= G;

      return t;
  }

  float pattern(in vec2 p) {
      vec2 q = vec2( fbm( p + vec2(0.0,0.0) ),
                     fbm( p + vec2(5.2,1.3) ) );

      vec2 r = vec2( fbm( p + 2.0*q + vec2(1.7,9.2) ),
                     fbm( p + 2.0*q + vec2(8.3,2.8) ) );

      return fbm( p + 2.*r );
  }

  void main() {
      vec2 st = gl_FragCoord.xy/u_resolution.xy;
      st.x *= u_resolution.x/u_resolution.y;

      st *= 10.;

      vec3 color = vec3(pow(pattern(st), 3.)*0.15);

      gl_FragColor = vec4(color,1.0);
  }
`;

// === Tab: vert ===
const vert = `
   attribute vec3 aPosition;
   attribute vec2 aTexCoord;
   uniform mat4 uProjectionMatrix;
   uniform mat4 uModelViewMatrix;
   varying vec2 vTexCoord;

   void main() {
     vTexCoord = aTexCoord;
     vec4 position = vec4(aPosition, 1.0);
     gl_Position = uProjectionMatrix * uModelViewMatrix * position;
   }
`;

